using Full.NET.Data.Abstractions;

namespace Full.NET.Modules.Ai.Persistence;

/// <summary>发布、读取保护和清理共用文档根锁；事务内只查询 AI 自有权威。</summary>
internal static partial class AiKnowledgePublicationSql
{
    private const string Root = " FROM fn_ai_knowledge_document AS document INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId WHERE document.Id=@DocumentId AND knowledge.Id=@KnowledgeBaseId";
    private const string Host = " AND knowledge.TenantId IS NULL";
    private const string Tenant = " AND knowledge.TenantId=@TenantId";
    private static string Locked(bool mysql, bool scoped) => "SELECT document.Id" + (mysql ? Root : Root.Replace(" AS document ", " AS document WITH(UPDLOCK,HOLDLOCK) ", StringComparison.Ordinal).Replace(" AS knowledge ", " AS knowledge WITH(UPDLOCK,HOLDLOCK) ", StringComparison.Ordinal)) + (scoped ? Tenant : Host) + (mysql ? " FOR UPDATE" : "");
    private static readonly SqlStatement LockSqlServerHost = new("ai.knowledge_publication.lock_sqlserver_host", Locked(false, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement LockSqlServerTenant = new("ai.knowledge_publication.lock_sqlserver_tenant", Locked(false, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private static readonly SqlStatement LockMySqlHost = new("ai.knowledge_publication.lock_mysql_host", Locked(true, false), SqlDataScope.HostOnly);
    private static readonly SqlStatement LockMySqlTenant = new("ai.knowledge_publication.lock_mysql_tenant", Locked(true, true), SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    internal static SqlStatement LockFor(DatabaseProvider provider, bool scoped) => provider == DatabaseProvider.MySql
        ? scoped ? LockMySqlTenant : LockMySqlHost : scoped ? LockSqlServerTenant : LockSqlServerHost;

    private const string Archive = "INSERT INTO fn_ai_knowledge_generation (Id,DocumentId,VersionId,PlanHash,ManifestHash,ReceiptHash,ReceiptJson,LeaseToken,ActivatedAtUtc,CleanupState) SELECT active.IndexTaskId,active.DocumentId,active.VersionId,active.PlanHash,active.ManifestHash,active.ReceiptHash,active.ReceiptJson,active.LeaseToken,active.ActivatedAtUtc,0 FROM fn_ai_knowledge_active_generation AS active INNER JOIN fn_ai_knowledge_document AS document ON document.Id=active.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId WHERE document.Id=@DocumentId AND knowledge.Id=@KnowledgeBaseId AND knowledge.OwnerUserId=@OwnerUserId AND active.IndexTaskId=@TaskId AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_generation WHERE Id=@TaskId)";
    internal static readonly SqlStatement ArchiveHost = new("ai.knowledge_publication.archive_host", Archive + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement ArchiveTenant = new("ai.knowledge_publication.archive_tenant", Archive + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string Lease = "INSERT INTO fn_ai_knowledge_read_lease (Id,GenerationId,TenantId,ActorUserId,ExpiresAtUtc,CreatedAtUtc) SELECT @Id,active.Id,knowledge.TenantId,@ActorUserId,CASE WHEN @PublicationId IS NULL THEN @ExpiresAtUtc ELSE (SELECT CASE WHEN ending.EffectiveToUtc<@ExpiresAtUtc THEN ending.EffectiveToUtc ELSE @ExpiresAtUtc END FROM fn_ai_knowledge_publication AS ending WHERE ending.Id=@PublicationId) END,@Now FROM fn_ai_knowledge_generation AS active INNER JOIN fn_ai_knowledge_document AS document ON document.Id=active.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId WHERE active.Id=@TaskId AND document.Id=@DocumentId AND knowledge.Id=@KnowledgeBaseId AND document.IsDeleted=0 AND knowledge.IsEnabled=1 AND active.CleanupState=0 AND EXISTS (SELECT 1 FROM fn_ai_knowledge_version AS version LEFT JOIN fn_ai_knowledge_import AS imported ON imported.VersionId=version.Id AND imported.FileId=version.FileId WHERE version.Id=active.VersionId AND version.DocumentId=document.Id AND ((version.FaqRevisionId IS NULL AND imported.StateKey='completed' AND imported.ContentHash=version.ContentHash) OR (" + AiKnowledgeFaqIndexSql.Origin + "))) AND ((@PublicationId IS NULL) OR EXISTS (SELECT 1 FROM fn_ai_knowledge_publication_head AS head INNER JOIN fn_ai_knowledge_publication AS publication ON publication.Id=head.PublicationId WHERE head.Id=document.Id AND publication.Id=@PublicationId AND publication.GenerationId=active.Id AND publication.StateKey='published' AND publication.EffectiveFromUtc<=@Now AND publication.EffectiveToUtc>@Now))";
    internal static readonly SqlStatement LeaseHost = new("ai.knowledge_publication.lease_host", Lease + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement LeaseTenant = new("ai.knowledge_publication.lease_tenant", Lease + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string Release = "DELETE FROM fn_ai_knowledge_read_lease WHERE Id=@Id AND ActorUserId=@ActorUserId AND EXISTS (SELECT 1 FROM fn_ai_knowledge_generation AS active INNER JOIN fn_ai_knowledge_document AS document ON document.Id=active.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId WHERE active.Id=GenerationId AND document.Id=@DocumentId AND knowledge.Id=@KnowledgeBaseId";
    internal static readonly SqlStatement ReleaseHost = new("ai.knowledge_publication.release_host", Release + Host + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement ReleaseTenant = new("ai.knowledge_publication.release_tenant", Release + Tenant + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string SourceRelease = "SELECT document.Id" + Root + " AND knowledge.OwnerUserId=@OwnerUserId AND NOT EXISTS (SELECT 1 FROM fn_ai_knowledge_generation AS active INNER JOIN fn_ai_knowledge_read_lease AS held ON held.GenerationId=active.Id WHERE active.DocumentId=document.Id AND held.ExpiresAtUtc>@Now)";
    internal static readonly SqlStatement SourceReleaseHost = new("ai.knowledge_publication.source_release_host", SourceRelease + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement SourceReleaseTenant = new("ai.knowledge_publication.source_release_tenant", SourceRelease + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string LeaseDeadline = "SELECT held.ExpiresAtUtc FROM fn_ai_knowledge_read_lease AS held INNER JOIN fn_ai_knowledge_generation AS active ON active.Id=held.GenerationId INNER JOIN fn_ai_knowledge_document AS document ON document.Id=active.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId WHERE held.Id=@Id AND held.ActorUserId=@ActorUserId AND document.Id=@DocumentId AND knowledge.Id=@KnowledgeBaseId";
    internal static readonly SqlStatement LeaseDeadlineHost = new("ai.knowledge_publication.lease_deadline_host", LeaseDeadline + Host, SqlDataScope.HostOnly);
    internal static readonly SqlStatement LeaseDeadlineTenant = new("ai.knowledge_publication.lease_deadline_tenant", LeaseDeadline + Tenant, SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
    private const string ExpireLeases = "DELETE FROM fn_ai_knowledge_read_lease WHERE GenerationId=@TaskId AND ExpiresAtUtc<=@Now AND EXISTS (SELECT 1 FROM fn_ai_knowledge_generation AS active INNER JOIN fn_ai_knowledge_document AS document ON document.Id=active.DocumentId INNER JOIN fn_ai_knowledge_base AS knowledge ON knowledge.Id=document.KnowledgeBaseId WHERE active.Id=@TaskId AND document.Id=@DocumentId AND knowledge.Id=@KnowledgeBaseId";
    internal static readonly SqlStatement ExpireLeasesHost = new("ai.knowledge_publication.expire_leases_host", ExpireLeases + Host + ")", SqlDataScope.HostOnly);
    internal static readonly SqlStatement ExpireLeasesTenant = new("ai.knowledge_publication.expire_leases_tenant", ExpireLeases + Tenant + ")", SqlDataScope.TenantRequired, SqlTenantBinding.CurrentTenantId);
}
